INSERT INTO draft_chapter (id, draft_id, import_batch_id, clause_no, parent_clause_no, level, sequence, title_cn, content_cn, title_en, content_en, illustration, clause_type, source_page, review_status, confidence, needs_review, import_key) VALUES (1,15,1,'1','',1,1,'适用范围','本章适用于室内物流机器人整机及其充电装置的电气安全评审。','Scope','This clause applies to the electrical safety review of indoor logistics robots and their charging equipment.',NULL,'Clause',NULL,NULL,NULL,NULL,'GBT47494-1');
INSERT INTO draft_chapter (id, draft_id, import_batch_id, clause_no, parent_clause_no, level, sequence, title_cn, content_cn, title_en, content_en, illustration, clause_type, source_page, review_status, confidence, needs_review, import_key) VALUES (2,15,1,'2','',1,2,'保护连接','外露可导电部分应可靠连接至保护导体。应按图 1 所示检查点测量保护连接电阻，并记录测量值。','Protective connections','Exposed conductive parts shall be reliably connected to the protective conductor. Measure the protective bonding resistance at the check points shown in Figure 1 and record the values.','图 1 保护连接检查点示意','Clause',NULL,NULL,NULL,NULL,'GBT47494-2');
INSERT INTO draft_chapter (id, draft_id, import_batch_id, clause_no, parent_clause_no, level, sequence, title_cn, content_cn, title_en, content_en, illustration, clause_type, source_page, review_status, confidence, needs_review, import_key) VALUES (3,122,2,'1','',1,1,'范围','本文件规定人形机器人安全要求。','Scope','This document specifies safety requirements for humanoid robots.',NULL,'条款','1','已核对',NULL,'Yes','GBT45271-1');
