INSERT INTO meeting (id, meeting_no, title, meeting_date, meeting_type, organizer, participants, key_discussions, overall_conclusion, material_link, next_meeting_date, created_at, created_by, updated_at, updated_by) VALUES (15,'MTG-2026-015','全国机器人标准化技术委员会服务机器人性能试验记录与复审准备专题会议','2026-08-14','专题组会','全国机器人标准化技术委员会服务机器人工作组','许清禾、叶知秋、顾星野','围绕服务机器人运动性能试验记录模板、样机配置、试验环境、原始数据追溯和标准复审建议进行集中审议。','统一试验记录模板及证据留存要求，形成标准复审问题清单，并由各责任人按计划补充验证材料。',NULL,NULL,'2026-08-14 09:00:00','许清禾','2026-08-14 16:30:00','许清禾');
INSERT INTO meeting (id, meeting_no, title, meeting_date, meeting_type, organizer, participants, key_discussions, overall_conclusion, material_link, next_meeting_date, created_at, created_by, updated_at, updated_by) VALUES (17,'MTG-2026-017','物流机器人电气安全标准实施准备专题工作组会议','2026-09-11','专题组会','物流机器人电气安全标准实施工作组','沈可欣、叶知秋、唐予安、周启明','围绕物流机器人电气安全相关标准的实施差距、机型覆盖、试验能力和整改计划进行逐项评审。','确认实施前检查范围和责任分工，未关闭差距纳入行动项跟踪，并在下一次工作组会议复核。',NULL,'2026-09-25','2026-09-11 09:00:00','沈可欣','2026-09-11 16:30:00','沈可欣');
INSERT INTO meeting (id, meeting_no, title, meeting_date, meeting_type, organizer, participants, key_discussions, overall_conclusion, material_link, next_meeting_date, created_at, created_by, updated_at, updated_by) VALUES (18,'MTG-2026-018','人形机器人安全与移动导航标准草案联合评审工作组会议','2026-09-28','WG 全体会','全国机器人标准化技术委员会机器人安全与导航联合工作组','周启明、叶知秋、顾星野、林知远','评审人形机器人通用安全要求征求意见稿，以及移动机器人导航与定位性能试验方法送审稿的试验边界、场景覆盖和判定规则。','形成征求意见处理清单和送审材料补充清单；关键试验场景由责任单位在下一轮会议前完成验证。',NULL,'2026-10-26','2026-09-28 09:00:00','周启明','2026-09-28 17:00:00','周启明');
INSERT INTO meeting (id, meeting_no, title, meeting_date, meeting_type, organizer, participants, key_discussions, overall_conclusion, material_link, next_meeting_date, created_at, created_by, updated_at, updated_by) VALUES (19,'MTG-2026-019','工业移动机器人无线通信可靠性标准报批协调工作组会议','2026-10-09','专题组会','全国物流机器人标准化工作组','沈可欣、唐予安、许清禾、周启明','核对无线通信可靠性标准报批稿中的漫游切换、时延、丢包和故障降级指标，确认验证材料及意见关闭情况。','原则同意报批文本，补充跨接入点漫游测试记录和异常降级说明后提交报批。',NULL,'2026-10-23','2026-10-09 09:00:00','沈可欣','2026-10-09 16:30:00','沈可欣');
