INSERT INTO comparison_change (id, comparison_id, row_key, sequence, before_nos, after_nos, change_type, revision_class, summary_cn, summary_en, reason_cn, reason_en, review_note) VALUES (1,1,'R001',1,'["1"]','["1"]','Unchanged','Unchanged','范围条款未变。','The scope clause is unchanged.','中英文内容一致，要求未变。','Both language versions retain the same requirement.','');
INSERT INTO comparison_change (id, comparison_id, row_key, sequence, before_nos, after_nos, change_type, revision_class, summary_cn, summary_en, reason_cn, reason_en, review_note) VALUES (2,1,'R002',2,'["5.1"]','["5.1"]','Modified','Substantive','急停复位后由可重新启动，改为须人工确认后才能启动。','Restart after emergency stop reset now requires manual confirmation.','新增启动前置条件，改变安全控制要求。','A new precondition for restart changes the safety control requirement.','');
INSERT INTO comparison_change (id, comparison_id, row_key, sequence, before_nos, after_nos, change_type, revision_class, summary_cn, summary_en, reason_cn, reason_en, review_note) VALUES (3,1,'R003',3,'["5.2"]','["5.2"]','Modified','Substantive','协作模式速度上限由 0.5 m/s 降至 0.3 m/s。','The collaborative-mode speed limit is reduced from 0.5 m/s to 0.3 m/s.','数值阈值改变。','The numerical threshold changes.','');
INSERT INTO comparison_change (id, comparison_id, row_key, sequence, before_nos, after_nos, change_type, revision_class, summary_cn, summary_en, reason_cn, reason_en, review_note) VALUES (4,1,'R004',4,'["6"]','["6", "6.1", "6.2"]','Split','Editorial','记录保存条款拆分为风险评估记录和试验记录两个条款。','Record retention is split into separate risk assessment and test record clauses.','两项保存义务均保留，仅调整结构。','Both retention obligations remain; only the structure changes.','');
INSERT INTO comparison_change (id, comparison_id, row_key, sequence, before_nos, after_nos, change_type, revision_class, summary_cn, summary_en, reason_cn, reason_en, review_note) VALUES (5,1,'R005',5,'["7"]','["8"]','Moved','Editorial','术语说明由第7条移至第8条。','The terminology note moves from Clause 7 to Clause 8.','内容和含义不变。','Content and meaning are unchanged.','');
INSERT INTO comparison_change (id, comparison_id, row_key, sequence, before_nos, after_nos, change_type, revision_class, summary_cn, summary_en, reason_cn, reason_en, review_note) VALUES (6,1,'R006',6,'[]','["9"]','Added','Substantive','新增故障原因和恢复确认人的记录要求。','A new requirement records the fault cause and the person confirming recovery.','新增记录义务。','A new record-keeping obligation is introduced.','');
INSERT INTO comparison_change (id, comparison_id, row_key, sequence, before_nos, after_nos, change_type, revision_class, summary_cn, summary_en, reason_cn, reason_en, review_note) VALUES (7,1,'R007',7,'["5"]','["5"]','Unchanged','Unchanged','安全要求父章节标题未变。','The safety requirements parent heading is unchanged.','章节号和标题一致，无正文要求。','The clause number and heading are identical; neither contains body requirements.','');
